"use client";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  FolderSimplePlusIcon as PhFolderPlus,
  UserPlusIcon as PhUserPlus,
  UploadSimpleIcon as PhUpload,
  SparkleIcon as PhSparkle,
  ArrowCounterClockwiseIcon as PhReset,
  FastForwardIcon as PhForward,
  CheckIcon as PhCheck,
} from "@phosphor-icons/react";

interface ActionDef {
  id: string;
  label: string;
  detail: string;
  icon: typeof PhFolderPlus;
}

const ACTIONS: ActionDef[] = [
  { id: "project", label: "New project", detail: "Start a blank workspace.", icon: PhFolderPlus },
  { id: "invite", label: "Invite teammate", detail: "Bring someone in to collaborate.", icon: PhUserPlus },
  { id: "import", label: "Import data", detail: "Bring in an existing spreadsheet.", icon: PhUpload },
];

const STORAGE_KEY = "ies-demo-v1";

interface StoredState {
  visits: number;
  usage: Record<string, number>;
  activity: { id: string; label: string; visit: number }[];
}

function loadState(): StoredState {
  if (typeof window === "undefined") return { visits: 0, usage: {}, activity: [] };
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return { visits: 0, usage: {}, activity: [] };
    const parsed = JSON.parse(raw) as StoredState;
    return { visits: parsed.visits ?? 0, usage: parsed.usage ?? {}, activity: parsed.activity ?? [] };
  } catch {
    return { visits: 0, usage: {}, activity: [] };
  }
}

function saveState(state: StoredState) {
  if (typeof window === "undefined") return;
  window.localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
}

function ResetIcon() {
  return <PhReset size={13} aria-hidden />;
}
function ForwardIcon() {
  return <PhForward size={13} aria-hidden />;
}
function SparkleIcon({ size = 14 }: { size?: number }) {
  return <PhSparkle size={size} weight="fill" aria-hidden />;
}
function CheckIcon() {
  return <PhCheck size={11} aria-hidden />;
}

interface IntelligentEmptyStateProps {
  className?: string;
}

export function IntelligentEmptyState({ className }: IntelligentEmptyStateProps) {
  const [state, setState] = useState<StoredState | null>(null);
  const [justCompleted, setJustCompleted] = useState<string | null>(null);
  const initRef = useRef(false);
  const celebrateTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);
  const shouldReduceMotion = useReducedMotion();

  useEffect(() => {
    const raf = requestAnimationFrame(() => {
      if (initRef.current) return;
      initRef.current = true;
      const loaded = loadState();
      const next = { ...loaded, visits: loaded.visits + 1 };
      saveState(next);
      setState(next);
    });
    return () => {
      cancelAnimationFrame(raf);
      if (celebrateTimeout.current) clearTimeout(celebrateTimeout.current);
    };
  }, []);

  const complete = (action: ActionDef) => {
    setState((prev) => {
      if (!prev) return prev;
      const next: StoredState = {
        ...prev,
        usage: { ...prev.usage, [action.id]: (prev.usage[action.id] ?? 0) + 1 },
        activity: [{ id: action.id, label: action.label, visit: prev.visits }, ...prev.activity].slice(0, 4),
      };
      saveState(next);
      return next;
    });
    setJustCompleted(action.id);
    if (celebrateTimeout.current) clearTimeout(celebrateTimeout.current);
    celebrateTimeout.current = setTimeout(() => setJustCompleted(null), 900);
  };

  const simulateNextVisit = () => {
    setState((prev) => {
      if (!prev) return prev;
      const next = { ...prev, visits: prev.visits + 1 };
      saveState(next);
      return next;
    });
  };

  const reset = () => {
    const fresh: StoredState = { visits: 1, usage: {}, activity: [] };
    saveState(fresh);
    setState(fresh);
    setJustCompleted(null);
  };

  return (
    <div className={className}>
      <div className="relative w-full overflow-hidden rounded-2xl border border-slate-200/70 bg-white/95 p-5 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
        <div className="flex items-center justify-between gap-3">
          <h3 className="text-sm font-semibold text-slate-900 dark:text-white">Your workspace</h3>
          <motion.button
            type="button"
            onClick={reset}
            aria-label="Reset demo"
            whileTap={shouldReduceMotion ? undefined : { scale: 0.9 }}
            className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-slate-400 dark:hover:bg-white/10 dark:hover:text-slate-300"
          >
            <ResetIcon />
          </motion.button>
        </div>

        {state === null ? (
          <div className="mt-4 min-h-[220px] animate-pulse space-y-3">
            <div className="h-4 w-3/5 rounded bg-slate-100 dark:bg-white/5" />
            <div className="h-16 w-full rounded-xl bg-slate-100 dark:bg-white/5" />
            <div className="h-16 w-full rounded-xl bg-slate-100 dark:bg-white/5" />
          </div>
        ) : (
          <EmptyStateBody
            state={state}
            justCompleted={justCompleted}
            onComplete={complete}
            shouldReduceMotion={shouldReduceMotion}
          />
        )}
      </div>

      <button
        type="button"
        onClick={simulateNextVisit}
        disabled={state === null}
        className="inline-flex items-center gap-1.5 self-center rounded-lg px-2 py-1 text-xs font-medium text-slate-400 transition-colors hover:text-slate-600 disabled:opacity-40 dark:hover:text-slate-300"
      >
        <ForwardIcon />
        Simulate next visit (currently visit {state?.visits ?? 1})
      </button>
      <p className="text-center text-xs text-slate-400 dark:text-slate-500">
        Real visit and click counts, kept in this browser. The state genuinely changes shape as they accumulate, it is not a scripted slideshow.
      </p>
    </div>
  );
}

function EmptyStateBody({
  state,
  justCompleted,
  onComplete,
  shouldReduceMotion,
}: {
  state: StoredState;
  justCompleted: string | null;
  onComplete: (action: ActionDef) => void;
  shouldReduceMotion: boolean | null;
}) {
  const { visits, usage, activity } = state;
  const tier: "guided" | "recap" | "personalized" = visits <= 1 ? "guided" : visits <= 4 ? "recap" : "personalized";

  const topActionId = Object.entries(usage).sort((a, b) => b[1] - a[1])[0]?.[0];
  const topAction = ACTIONS.find((a) => a.id === topActionId);

  return (
    <div className="mt-4">
      <AnimatePresence mode="wait" initial={false}>
        {tier === "guided" && (
          <motion.div
            key="guided"
            initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 6 }}
            animate={{ opacity: 1, y: 0 }}
            exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -6 }}
            transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
          >
            <p className="text-xs text-slate-400 dark:text-slate-500">Nothing here yet. Start with the one thing that unlocks everything else.</p>
          </motion.div>
        )}

        {tier === "recap" && (
          <motion.div
            key="recap"
            initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 6 }}
            animate={{ opacity: 1, y: 0 }}
            exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -6 }}
            transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
          >
            <p className="text-xs font-medium text-slate-500 dark:text-slate-400">Welcome back. Here is what you did last time.</p>
            {activity.length > 0 ? (
              <ul className="mt-2 space-y-1.5">
                {activity.slice(0, 3).map((item, i) => (
                  <li key={`${item.id}-${i}`} className="flex items-center gap-2 text-xs text-slate-500 dark:text-slate-400">
                    <span className="flex h-4 w-4 shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400">
                      <CheckIcon />
                    </span>
                    {item.label}
                    <span className="text-slate-300 dark:text-slate-600">visit {item.visit}</span>
                  </li>
                ))}
              </ul>
            ) : (
              <p className="mt-2 text-xs text-slate-400 dark:text-slate-500">No actions taken yet, try one below.</p>
            )}
          </motion.div>
        )}

        {tier === "personalized" && topAction && (
          <motion.div
            key="personalized"
            initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 6 }}
            animate={{ opacity: 1, y: 0 }}
            exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -6 }}
            transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
          >
            <button
              type="button"
              onClick={() => onComplete(topAction)}
              className="group relative flex w-full items-center gap-3 overflow-hidden rounded-xl border border-emerald-200 bg-emerald-50/80 p-3 text-left transition-colors hover:bg-emerald-50 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-emerald-500/25 dark:bg-emerald-500/10 dark:hover:bg-emerald-500/15"
            >
              <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-emerald-600 text-white">
                <SparkleIcon />
              </span>
              <span className="min-w-0 flex-1">
                <span className="flex items-center gap-1.5 text-xs font-medium text-emerald-700 dark:text-emerald-300">
                  <SparkleIcon size={11} />
                  You do this a lot
                </span>
                <span className="mt-0.5 block truncate text-sm font-medium text-slate-800 dark:text-slate-100">{topAction.label}</span>
              </span>
            </button>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="mt-3 space-y-2">
        {ACTIONS.map((action) => {
          const isPrimary = tier === "guided" && action.id === ACTIONS[0].id;
          const isTop = tier === "personalized" && action.id === topActionId;
          const Icon = action.icon;
          const clicks = usage[action.id] ?? 0;
          return (
            <div key={action.id} className="relative">
              {isPrimary && !shouldReduceMotion && (
                <motion.span
                  aria-hidden
                  className="absolute inset-0 rounded-xl bg-emerald-500/20"
                  animate={{ opacity: [0.5, 0, 0.5] }}
                  transition={{ duration: 1.8, repeat: Infinity, ease: "easeInOut" }}
                />
              )}
              <motion.button
                type="button"
                onClick={() => onComplete(action)}
                whileTap={shouldReduceMotion ? undefined : { scale: 0.98 }}
                className={`relative flex w-full items-center gap-3 rounded-xl border p-3 text-left transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
                  isPrimary
                    ? "border-emerald-300 bg-white dark:border-emerald-500/40 dark:bg-neutral-900"
                    : isTop
                      ? "border-slate-200/70 bg-white/60 opacity-70 dark:border-white/10 dark:bg-white/5"
                      : "border-slate-200/70 bg-white/60 hover:border-slate-300 dark:border-white/10 dark:bg-white/5 dark:hover:border-white/20"
                }`}
              >
                <span
                  className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-lg ${
                    isPrimary ? "bg-emerald-600 text-white" : "bg-slate-100 text-slate-500 dark:bg-white/10 dark:text-slate-400"
                  }`}
                >
                  <Icon size={16} aria-hidden />
                </span>
                <span className="min-w-0 flex-1">
                  <span className="block text-sm font-medium text-slate-800 dark:text-slate-100">{action.label}</span>
                  <span className="block truncate text-xs text-slate-400 dark:text-slate-500">{action.detail}</span>
                </span>
                <AnimatePresence>
                  {justCompleted === action.id && (
                    <motion.span
                      initial={{ opacity: 0, scale: 0.5 }}
                      animate={{ opacity: 1, scale: 1 }}
                      exit={{ opacity: 0, scale: 0.5 }}
                      transition={{ type: "spring", stiffness: 500, damping: 26 }}
                      className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-emerald-600 text-white"
                    >
                      <CheckIcon />
                    </motion.span>
                  )}
                </AnimatePresence>
                {clicks > 0 && justCompleted !== action.id && (
                  <span className="shrink-0 tabular-nums text-xs text-slate-300 dark:text-slate-600">&times;{clicks}</span>
                )}
              </motion.button>
            </div>
          );
        })}
      </div>
    </div>
  );
}
